"""ADMITTED by the old bundle, REJECTED by the reference: G(z) = -z.

The sign flip (mean - x)/std is a one-character typo. Zero mean, unit variance and shift
invariance are all symmetric under y -> -y, so the old bundle cannot see it.
"""

import numpy as np


def _to_sphere(w, dtype):
    """Project each row of w onto S_n = {y : sum y = 0, |y|^2 = n}; a zero row maps to 0."""
    w = np.asarray(w, dtype=np.float64)
    z = w - w.mean(axis=-1, keepdims=True)
    norm = np.sqrt(np.sum(z * z, axis=-1, keepdims=True))
    safe = np.where(norm > 0, norm, 1.0)
    return np.where(norm > 0, z * (np.sqrt(z.shape[-1]) / safe), 0.0).astype(dtype)


def _center(x):
    w = np.asarray(x, dtype=np.float64)
    return w - w.mean(axis=-1, keepdims=True)


def layernorm(x: np.ndarray) -> np.ndarray:
    z = _center(x)
    return _to_sphere(-z, x.dtype)

