The wrong operator altogether -- a (stable) row softmax -- followed by exact
standardization onto the sphere. Softmax is itself shift invariant, so the composition
is too; the output is monotone in the input but not affine in it. A plausible outcome of
a kernel author fusing the wrong epilogue.
"""

import numpy as np


def _to_sphere(w, dtype):
    w = np.asarray(w, dtype=np.float64)
    z = w - w.mean(axis=-1, keepdims=True)
    norm = np.sqrt(np.sum(z * z, axis=-1, keepdims=True))
    safe = np.where(norm > 0, norm, 1.0)
    return np.where(norm > 0, z * (np.sqrt(z.shape[-1]) / safe), 0.0).astype(dtype)


def _center(x):
    w = np.asarray(x, dtype=np.float64)
    return w - w.mean(axis=-1, keepdims=True)


def layernorm(x: np.ndarray) -> np.ndarray:
    z = _center(x)
    e = np.exp(z - z.max(axis=-1, keepdims=True))
    return _to_sphere(e / e.sum(axis=-1, keepdims=True), x.dtype)

"""CORRECT VARIANT: the textbook two-pass layernorm accumulated entirely in float32."""

import numpy as np

EPS = np.float32(1e-5)


def layernorm(x: np.ndarray) -> np.ndarray:
    x32 = np.asarray(x, dtype=np.float32)
    mean = np.mean(x32, axis=-1, keepdims=True, dtype=np.float32)
    centered = x32 - mean
    var = np.mean(centered * centered, axis=-1, keepdims=True, dtype=np.float32)
    return (centered / np.sqrt(var + EPS)).astype(x.dtype)

