"""Shared helpers for the probes: per-group verdicts for any set of arms, plus kernel builders.

Everything here goes through gate.py's own machinery (same cases, same oracles), so a
probe's numbers are the gate's numbers.
"""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

import numpy as np  # noqa: E402

import gate  # noqa: E402
from autokernel_pbt.props.oracle import DeclarativeOracle, ReferenceOracle, summary  # noqa: E402
from autokernel_pbt.props.verdict import Verdict  # noqa: E402

RESULTS = ROOT / "results"
RESULTS.mkdir(exist_ok=True)

EPS32 = float(np.finfo(np.float32).eps)


def load_kernel(path: Path):
    return gate.load_kernel(path)


def old_bundle() -> DeclarativeOracle:
    return gate.declarative(include_laws=False)


def completed_bundle() -> DeclarativeOracle:
    return gate.declarative(include_laws=True)


def with_extra_laws(case_laws=(), group_laws=()) -> DeclarativeOracle:
    """The OLD bundle plus the given laws (used to score alternative completions)."""
    base = old_bundle()
    return DeclarativeOracle(
        [*base.case_properties, *case_laws], [*base.group_properties, *group_laws]
    )


def per_group(kernel, arms: dict[str, object]) -> dict[str, dict[str, tuple[str, str]]]:
    """arm -> group_id -> (verdict, first failing detail). Mirrors gate.check per group."""
    by_group = gate.rows_by_group(kernel)
    out: dict[str, dict[str, tuple[str, str]]] = {}
    for name, arm in arms.items():
        out[name] = {}
        for gid, rows in by_group.items():
            results = arm.evaluate(rows)
            verdict = summary(results)
            detail = ""
            if verdict is Verdict.FAIL:
                bad = next(r for r in results if r.verdict is Verdict.FAIL)
                detail = f"{bad.property_name}: {bad.detail}"
            out[name][gid] = (str(verdict), detail)
    return out


def failed(groups: dict[str, tuple[str, str]]) -> int:
