def to_sphere(w, dtype):
    """Project rows onto S_n = {y : sum y = 0, |y|^2 = n}; zero rows -> 0."""
    w = np.asarray(w, dtype=np.float64)
    z = w - w.mean(axis=-1, keepdims=True)
    norm = np.sqrt(np.sum(z * z, axis=-1, keepdims=True))
    safe = np.where(norm > 0, norm, 1.0)
    return np.where(norm > 0, z * (np.sqrt(z.shape[-1]) / safe), 0.0).astype(dtype)


def center(x):
    w = np.asarray(x, dtype=np.float64)
    return w - w.mean(axis=-1, keepdims=True)


def helmert(n):
    q = np.zeros((n, n - 1))
    for k in range(1, n):
        q[:k, k - 1] = 1.0
        q[k, k - 1] = -k
        q[:, k - 1] /= np.sqrt(k * (k + 1))
    return q


def rotation_kernel(theta: float):
    """Reference rotated by theta inside the zero-mean hyperplane (identity for n < 3)."""

    def layernorm(x):
        z = center(x)
        n = z.shape[-1]
        if n < 3:
            return to_sphere(z, x.dtype)
        q = helmert(n)
        g = np.eye(n - 1)
        c, s = np.cos(theta), np.sin(theta)
        g[0, 0], g[0, 1], g[1, 0], g[1, 1] = c, -s, s, c
        rot = q @ g @ q.T + np.ones((n, n)) / n
        return to_sphere(z @ rot.T, x.dtype)

    return layernorm


def eps_kernel(eps: float, outside: bool = False):
    """The reference with a different eps, inside (default) or outside the square root."""

    def layernorm(x):
        w = np.asarray(x, dtype=np.float64)
        mean = np.mean(w, axis=-1, keepdims=True)
        zc = w - mean
        var = np.mean(zc * zc, axis=-1, keepdims=True)
        denom = np.sqrt(var) + eps if outside else np.sqrt(var + eps)
        if eps == 0.0 and not outside:
            denom = np.where(denom > 0, denom, 1.0)
        return (zc / denom).astype(x.dtype)

    return layernorm


def md_table(headers: list[str], rows: list[list[str]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)

"""Laws that are EQUIVALENT to the direction law in exact arithmetic are not equivalent gates.

Four ways to say "y points along z" (RESULT.md, R3):

  affine_residual   ||y - (a z + b)||_inf small, a > 0        (laws.py; first-order in the angle)
  correlation_one   <y,z> / (|y| |z|) = 1                     (Cauchy-Schwarz equality; 1 - cos t = t^2/2,
                                                               SECOND-order blind)
  order_preserved   sign(y_i - y_j) in {0, sign(z_i - z_j)}   (tolerance-free, but admits every monotone G)
  extremes_match    argmax y = argmax z, argmin y = argmin z   (tolerance-free, weaker still)

Each is scored as the ONLY addition to the old bundle, against every admitted kernel, the
reference, the correct variants, and a sweep of rotation angles. Writes
results/alternative_laws.md.
"""

